class Solution {
public:
    int subarraySum(std::vector<int>& nums, int k) {
        // We track the cumulative sum and how often it has occurred.
        std::unordered_map<int, int> history;
        history[0] = 1; 

        int current_sum = 0;
        int count = 0;

        for (int val : nums) {
            current_sum += val;

            // If the difference exists in our history, we've found a path.
            if (history.find(current_sum - k) != history.end()) {
                count += history[current_sum - k];
            }

            // Record this sum for future reference.
            history[current_sum]++;
        }

        return count;
    }
};
```

