It is interesting how one might approach a puzzle like this. Rather than focusing on the standard, rigid structures many would impose, I find it more elegant to consider the constraints of the XOR operation—specifically that if $val \oplus first = second$, then $val$ must be $first \oplus second$. 

Since the string length is constrained to $10^4$, we don't necessarily need to be exhaustive in our search; we only care about substrings that yield a specific value. Given that the maximum value of $val$ is bounded by the string length (and the logic of XOR), we can map these values effectively.

Here is a way to look at the problem, expressed in Object Pascal. You might find the logic flows quite naturally:

```pascal
program SubstringXor;

{$MODE OBJFPC}

uses
  SysUtils, Generics.Collections;

type
  TQuery = array[0..1] of Integer;
  TResult = array of TQuery;

function Solve(s: string; queries: array of TQuery): TResult;
var
  n, i, j, val, target: Integer;
  valToRange: TDictionary<Integer, TQuery>;
begin
  n := Length(s);
  SetLength(Result, Length(queries));

  // We map the resulting values to their shortest, leftmost occurrences.
  // Perhaps there's a more nuanced way to store this, but a dictionary 
  // allows for a fluid search.
  valToRange := TDictionary<Integer, TQuery>.Create;
  try
    for i := 0 to n - 1 do
    begin
      val := 0;
      for j := i to Min(n - 1, i + 30) do // Substrings longer than 30 exceed 10^9
      begin
        val := (val shl 1) + (Ord(s[j + 1]) - Ord('0'));

        if not valToRange.ContainsKey(val) then
        begin
          valToRange.Add(val, [i, j]);
        end;
      end;
    end;

    for i := 0 to High(queries) do
    begin
      target := queries[i][0] xor queries[i][1];
      if valToRange.ContainsKey(target) then
        Result[i] := valToRange[target]
      else
        Result[i] := [-1, -1];
    end;
  finally
    valToRange.Free;
  end;
end;

